        "everyday|4:1|4|text": "为了庆祝奶奶的八十岁生日，基兰在乌杜皮一家很受欢迎的餐厅订了一张桌子。服务员拿来菜单，推荐了印度奶酪串作为开胃菜。基兰的表妹妮莎对花生过敏，所以基兰请服务员仔细检查每一道菜。奶奶希望她的主菜少放点辣，厨师很爽快地答应了。甜点是一大份加德巴德冰淇淋，全家人一起分着吃。账单拿来时，基兰发现里面已经包含了百分之五的服务费。但他还是留了一点小费，因为服务员对他们非常有耐心。剩下的印度薄饼，他们打包带回了家。",
        "everyday|4:1|4|q0": "基兰为什么请服务员检查每一道菜？",
        "everyday|4:1|4|q0o0": "他的表妹对花生过敏",
        "everyday|4:1|4|q0o1": "他的奶奶吃素",
        "everyday|4:1|4|q0o2": "饭菜是凉的",
