        "everyday|4:1|5|title": "点晚餐",
        "everyday|4:1|5|scenario": "阿南雅和一个朋友在浦那的一家餐厅吃饭。服务员马诺吉过来给她们点菜。",
        "everyday|4:1|5|l0": "女士，晚上好。现在可以点菜了吗？还是您需要再看几分钟？",
        "everyday|4:1|5|l1": "我们应该可以点了。今天的特色菜是什么？",
        "everyday|4:1|5|l2": "今天有马尔瓦尼咖喱鱼和素食塔利套餐。",
        "everyday|4:1|5|l3": "给我朋友来一份塔利套餐。咖喱鱼很辣吗？",
        "everyday|4:1|5|l4": "挺辣的，不过如果您愿意，厨师可以做得不那么辣。",
        "everyday|4:1|5|l5": "好的，请少放点辣。另外，我朋友对坚果过敏，套餐里请不要放腰果。",
        "everyday|4:1|5|l6": "好的，我会告诉厨房。要喝点什么吗？",
        "everyday|4:1|5|l7": "两杯甜拉西，谢谢。最后可以用UPI付款吗？",
        "everyday|4:1|5|l8": "当然可以，我们收UPI，也可以刷卡。饮料马上就来。",
        "everyday|4:1|5|l9": "谢谢，你真好。",
