        "everyday|5:1|4|title": "马迪凯里吵闹的一夜",
        "everyday|5:1|4|text": "尼基尔和妻子施蕾娅在马迪凯里的一家小酒店预订了房间，准备在那里过一个长周末。办理入住时，前台给了他们一间一楼的大床房。那天夜里，空调发出很响的咔嗒声，房间又热得让人睡不着。尼基尔给前台打电话，礼貌地投诉了。经理道了歉，把他们换到楼上一间更安静的房间，还能看到远处的山。第二天早上，客房保洁人员主动送来了干净的毛巾和多余的枕头。退房时，经理请他们免费吃了一顿早餐，作为对这次麻烦的补偿。",
        "everyday|5:1|4|q0": "第一间房有什么问题？",
        "everyday|5:1|4|q0o0": "空调很吵",
        "everyday|5:1|4|q0o1": "没有毛巾",
