        "everyday|5:1|4|q0o3": "门锁不上",
        "everyday|5:1|4|q1": "经理是怎么处理投诉的？",
        "everyday|5:1|4|q1o0": "把他们换到更安静的房间",
        "everyday|5:1|4|q1o1": "给他们全额退款",
        "everyday|5:1|4|q1o2": "请他们离开",
        "everyday|5:1|4|q1o3": "下个星期派了一个修理工",
        "everyday|5:1|4|q2": "他们退房时得到了什么？",
        "everyday|5:1|4|q2o0": "一顿免费早餐",
