        "everyday|5:1|4|q2o2": "一盒咖啡粉",
        "everyday|5:1|4|q2o3": "延迟退房",
        "everyday|5:1|5|title": "办理入住",
        "everyday|5:1|5|scenario": "拉胡尔傍晚到了胡布利的一家酒店，前台的法拉为他办理入住。",
        "everyday|5:1|5|l0": "先生，晚上好，欢迎光临桑加姆酒店。请问您有预订吗？",
        "everyday|5:1|5|l1": "有，名字是拉胡尔·乔希，订了三个晚上。",
        "everyday|5:1|5|l2": "好的，我看到了：一间大床房，住到星期五。可以看一下您带照片的身份证件吗？",
        "everyday|5:1|5|l3": "这是我的阿达尔卡。房价包含早餐吗？",
        "everyday|5:1|5|l4": "包含的。早餐在餐厅供应，时间是七点到十点。",
        "everyday|5:1|5|l5": "太好了。能不能给我一间离电梯远一点的房间？我睡觉很轻。",
        "everyday|5:1|5|l6": "当然可以。给您312房间，在走廊安静的那一头。",
        "everyday|5:1|5|l7": "谢谢。星期五几点退房？",
        "everyday|5:1|5|l8": "十一点退房，不过如果您需要多一点时间，请告诉我们。",
        "everyday|5:1|5|l9": "这样真是太好了，非常感谢。",
        "everyday|5:1|5|q0": "拉胡尔要住几个晚上？",
