        "everyday|6:1|3|p0": "因为德里附近有大雾，火车延误了四个小时。",
        "everyday|6:1|3|p1": "如果提前两天以上取消，取消费很低。",
        "everyday|6:1|3|p2": "大巴取消了，所以我去问讯处申请退款。",
        "everyday|6:1|3|p3": "你听清楚刚才的广播了吗？我们得把行李搬到五号站台。",
        "everyday|6:1|3|p4": "根据时刻表，去迈索尔的末班车十点发车。",
        "everyday|6:1|4|title": "及时赶到",
        "everyday|6:1|4|text": "阿莎要从胡布利去浦那参加姐姐的婚礼。她两个月前就订好了座位，是S4车厢的下铺。到了车站，广播说火车要延误三个小时。阿莎在手机上查了大巴时刻表，找到一班能更早到达浦那的大巴。她在网上取消了火车票，两天后退款就到了她的账户。一位搬运工收了一点费用，帮她把沉重的行李搬到了汽车站。她及时赶到了浦那，正好赶上海娜手绘仪式。",
        "everyday|6:1|4|q0": "阿莎为什么去浦那？",
