        "everyday|6:1|4|q2o0": "坐大巴",
        "everyday|6:1|4|q2o1": "坐晚一点的火车",
        "everyday|6:1|4|q2o2": "坐飞机",
        "everyday|6:1|4|q2o3": "坐出租车",
        "everyday|6:1|5|title": "被取消的火车",
        "everyday|6:1|5|scenario": "在迈索尔火车站，卡维塔发现她去班加罗尔的火车取消了，于是向问讯处的苏雷什求助。",
        "everyday|6:1|5|l0": "打扰一下，我刚听到广播说查蒙迪快车取消了，是真的吗？",
        "everyday|6:1|5|l1": "恐怕是的，女士。曼迪亚附近的铁轨出了问题。",
        "everyday|6:1|5|l2": "糟了。我两点在班加罗尔有个重要的会议。我还有什么办法？",
        "everyday|6:1|5|l3": "十一点十五分有一班快车，从三号站台出发，一般一点半之前到。",
        "everyday|6:1|5|l4": "那班车还有座位吗？",
        "everyday|6:1|5|l5": "恐怕只有普通车厢了。对号座位都已经在排候补了。",
        "everyday|6:1|5|l6": "普通车厢也行。那我被取消的票怎么办？",
        "everyday|6:1|5|l7": "因为是铁路部门取消的列车，您会在一周内拿到全额退款。",
        "everyday|6:1|5|l8": "退款需要填表吗？",
        "everyday|6:1|5|l9": "不需要，女士。您是在网上订的票，所以会自动退款。祝您一路平安。",
        "everyday|6:1|5|q0": "查蒙迪快车为什么被取消了？",
        "everyday|6:1|5|q0o0": "曼迪亚附近的铁轨出了问题",
