        "opinions|1:1|0|w0": "观点",
        "opinions|1:1|0|w1": "在我看来",
        "opinions|1:1|0|w2": "就我而言",
        "opinions|1:1|0|w3": "立场",
        "opinions|1:1|0|w4": "信念",
        "opinions|1:1|0|w5": "坦白说",
        "opinions|1:1|1|p0": "在我看来，每个孩子都应该至少学一种乐器。",
        "opinions|1:1|1|p1": "就我而言，新的公交时刻表改进了很多。",
        "opinions|1:1|1|p2": "对于在教室里使用手机，你的立场是什么？",
        "opinions|1:1|1|p3": "她说话时充满信念，屋里没有一个人跟她争论。",
        "opinions|1:1|1|p4": "坦白说，我觉得这部电影太长了，而且挺无聊的。",
