        "opinions|5:1|1|p0": "兄弟俩为了一小块地吵了一架。",
        "opinions|5:1|1|p1": "这完全是个误会，她从来没想过要伤害你。",
        "opinions|5:1|1|p2": "冷战了一个星期后，两个朋友终于边喝茶边和好了。",
        "opinions|5:1|1|p3": "心怀怨恨只会伤害你自己，试着原谅别人，继续向前走吧。",
        "opinions|5:1|1|p4": "我爸妈吵架时，我从不偏袒一方，只给他们俩各泡一杯茶。",
        "opinions|5:1|2|w0": "值得信赖",
