        "opinions|5:1|2|w3": "保持联系",
        "opinions|5:1|2|w4": "渐渐疏远",
        "opinions|5:1|2|w5": "亲情",
        "opinions|5:1|3|p0": "值得信赖的朋友，就算跟你吵过架，也会替你保守秘密。",
        "opinions|5:1|3|p1": "我会向姐姐倾诉心事，因为她从不评判我。",
        "opinions|5:1|3|p2": "每个星期天一起做饭，让我和爸爸之间的感情纽带更牢固了。",
        "opinions|5:1|3|p3": "我们约好要保持联系，可大学毕业后还是渐渐疏远了。",
        "opinions|5:1|3|p4": "在印度家庭里，亲情往往能延续好几代，依然牢固。",
        "opinions|5:1|4|title": "希莫加的两个朋友",
        "opinions|5:1|4|text": "阿伦和普拉卡什在希莫加是隔壁邻居，从小一起长大，什么都一起分享，从板球拍到秘密。上大学时，普拉卡什以为阿伦把他的秘密告诉了别人，两人大吵了一架。其实那只是一场误会，但两个人都太要面子，谁也不肯先打电话。他们五年没有说话，朋友们也不愿偏袒任何一方。阿伦的妈妈两个孩子都很疼爱，一直盼着他们能和好。在普拉卡什妹妹的婚礼上，两人终于面对面站在了一起。普拉卡什说：“我为了一个可笑的理由记恨了你这么久，请原谅我。”阿伦拥抱了他。从那天起，他们每个星期都保持联系。",
        "opinions|5:1|4|q0": "普拉卡什为什么生阿伦的气？",
        "opinions|5:1|4|q0o0": "他以为阿伦把他的秘密告诉了别人",
        "opinions|5:1|4|q0o1": "阿伦弄坏了他的板球拍",
        "opinions|5:1|4|q0o2": "阿伦没去参加他妹妹的婚礼",
        "opinions|5:1|4|q0o3": "阿伦没有还钱",
        "opinions|5:1|4|q1": "他们多久没有说话？",
        "opinions|5:1|4|q1o0": "五年",
        "opinions|5:1|4|q1o1": "五个月",
        "opinions|5:1|4|q1o2": "两年",
        "opinions|5:1|4|q1o3": "十年",
        "opinions|5:1|4|q2": "他们最后在哪里重逢？",
        "opinions|5:1|4|q2o0": "在普拉卡什妹妹的婚礼上",
        "opinions|5:1|4|q2o1": "在一场板球比赛上",
        "opinions|5:1|4|q2o2": "在阿伦家",
        "opinions|5:1|4|q2o3": "在他们的母校",
        "opinions|5:1|5|title": "和好",
        "opinions|5:1|5|scenario": "阿卡什去贝尔高姆看他的大学朋友斯米塔。她已经一个星期没理他了。",
        "opinions|5:1|5|l0": "斯米塔，我们能谈一会儿吗？我知道你在生我的气。",
        "opinions|5:1|5|l1": "生气？你答应来看我的舞蹈表演，结果连个电话都没打。",
        "opinions|5:1|5|l2": "你说得对，我真的很抱歉。那天晚上我奶奶被送进了医院。",
        "opinions|5:1|5|l3": "天哪！你为什么不告诉我？我还以为你根本不在乎。",
        "opinions|5:1|5|l4": "我的手机没电了，后来又不好意思解释。这是个愚蠢的误会。",
        "opinions|5:1|5|l5": "要是你早点告诉我就好了。我生了你整整一个星期的气。",
        "opinions|5:1|5|l6": "我理解。你能原谅我吗？我们的友谊对我来说很重要。",
        "opinions|5:1|5|l7": "当然。你是我认识的最值得信赖的人之一。你奶奶现在怎么样了？",
        "opinions|5:1|5|l8": "好多了，谢谢。她已经回家了，又开始对大家发号施令了！",
        "opinions|5:1|5|l9": "这很像她的作风。下次答应我，就算手机没电，也要跟我保持联系！",
        "opinions|5:1|5|q0": "斯米塔为什么生气？",
        "opinions|5:1|5|q0o0": "阿卡什没来看她的舞蹈表演",
        "opinions|5:1|5|q0o1": "阿卡什忘了她的生日",
        "opinions|5:1|5|q0o2": "阿卡什说出了她的秘密",
        "opinions|5:1|5|q0o3": "阿卡什弄丢了她的笔记",
        "opinions|5:1|5|q1": "阿卡什为什么没能来？",
        "opinions|5:1|5|q1o0": "他奶奶被送进了医院",
        "opinions|5:1|5|q1o1": "他要考试",
