        "opinions|6:1|1|p0": "谢谢你的建议，我这周就试试。",
        "opinions|6:1|1|p1": "给你一句忠告：没看过的文件千万不要签字。",
        "opinions|6:1|1|p2": "如果我是你，我会在事情闹大之前先向她道歉。",
        "opinions|6:1|1|p3": "你最好现在就走，不然会赶不上去哈桑的末班车。",
        "opinions|6:1|1|p4": "你不如跟我一起参加卡邦公园的晨走小组吧？",
        "opinions|6:1|2|w0": "两难",
        "opinions|6:1|2|w1": "左右为难",
        "opinions|6:1|2|w2": "参谋",
        "opinions|6:1|2|w3": "听从",
        "opinions|6:1|2|w4": "好好想想",
        "opinions|6:1|2|w5": "半信半疑",
        "opinions|6:1|3|p0": "我真的很两难：是去浦那工作，还是留在家里？",
        "opinions|6:1|3|p1": "她在学艺术和进家族企业之间左右为难。",
        "opinions|6:1|3|p2": "每当我要做重大决定时，我叔叔都是我的好参谋。",
        "opinions|6:1|3|p3": "他没有听从医生的警告，结果又病倒了。",
        "opinions|6:1|3|p4": "好好想想，对网上的评论要半信半疑。",
        "opinions|6:1|4|title": "奶奶的忠告",
        "opinions|6:1|4|text": "乌杜皮的斯内哈遇到了两难：她被艾哈迈达巴德的一所设计学院录取了，可父母希望她在离家近的地方上学。她在梦想和家人之间左右为难，于是去找奶奶——奶奶一直是她的好参谋。奶奶静静地听完，然后说：“如果我是你，我不会急着做决定，先好好想几天。”她还给了斯内哈一句忠告：对亲戚们的议论要半信半疑。“我的经验法则很简单，”奶奶补充道，“选一条到了六十岁也不会后悔的路。”接着她提了个建议：“你不如把学院的网站和你的作品集给爸妈看看？”斯内哈听从了她的建议，父母看了她的作品之后同意了。如今，她每个星期天都给奶奶打电话，把课上的事全都讲给她听。",
        "opinions|6:1|4|q0": "斯内哈面临什么两难？",
        "opinions|6:1|4|q0o0": "是去艾哈迈达巴德学设计，还是留在家附近",
        "opinions|6:1|4|q0o1": "是学音乐还是学舞蹈",
        "opinions|6:1|4|q0o2": "是买笔记本电脑还是买手机",
        "opinions|6:1|4|q0o3": "是搬到迈索尔还是门格洛尔",
        "opinions|6:1|4|q1": "关于亲戚们的议论，奶奶是怎么说的？",
        "opinions|6:1|4|q1o0": "要半信半疑",
        "opinions|6:1|4|q1o1": "要认真照着做",
        "opinions|6:1|4|q1o2": "要把它们记下来",
        "opinions|6:1|4|q1o3": "要和每个亲戚争论",
        "opinions|6:1|4|q2": "最后是什么说服了斯内哈的父母？",
        "opinions|6:1|4|q2o0": "看到了她的作品",
        "opinions|6:1|4|q2o1": "学院打来的电话",
        "opinions|6:1|4|q2o2": "奶奶写的一封生气的信",
        "opinions|6:1|4|q2o3": "一份奖学金",
        "opinions|6:1|5|title": "吵闹的室友",
        "opinions|6:1|5|scenario": "迪帕克是达尔瓦德的一名大一新生，他打电话给表姐莎莉妮，向她请教宿舍室友的事。",
        "opinions|6:1|5|l0": "莎莉妮姐，我能向你请教一件事吗？我不知道还能跟谁说。",
        "opinions|6:1|5|l1": "当然可以，迪帕克。有什么心事？",
        "opinions|6:1|5|l2": "我宿舍的室友把音乐放得很大声，一直放到凌晨两点，我根本睡不着。",
        "opinions|6:1|5|l3": "听起来真累人。你跟他说过这对你有什么影响吗？",
        "opinions|6:1|5|l4": "没怎么说过。我怕我们会吵架，而且我们一整年都得住在一起。",
        "opinions|6:1|5|l5": "如果我是你，我会找一个你们俩都放松的时候，心平气和地跟他谈谈。",
        "opinions|6:1|5|l6": "这是个好建议。可是我具体该说什么呢？",
        "opinions|6:1|5|l7": "一个好的经验法则是：谈你自己遇到的问题，而不是数落他的缺点。你不如建议他十一点以后戴耳机？",
        "opinions|6:1|5|l8": "听起来很公平。我好好想想，这个周末就跟他谈。",
        "opinions|6:1|5|l9": "好。你最好别拖太久，不然考试的时候你会睡着的！",
        "opinions|6:1|5|q0": "迪帕克遇到了什么问题？",
        "opinions|6:1|5|q0o0": "他的室友深夜把音乐放得很大声",
        "opinions|6:1|5|q0o1": "他的室友从不打扫房间",
        "opinions|6:1|5|q0o2": "他的室友老借他的钱",
        "opinions|6:1|5|q0o3": "他的室友起得太早",
        "opinions|6:1|5|q1": "迪帕克为什么还没跟室友谈？",
