        "services|1:1|4|title": "深夜的药店",
        "services|1:1|4|text": "在迈索尔的一个晚上，十点钟，米拉的弟弟罗翰醒来时发起了高烧。他们的家庭医生不在城里，所以米拉打电话向她请教。医生说，先喝退烧糖浆，撑到早上就行了。米拉在汽车站附近找到了一家通宵营业的药店。她告诉药剂师，罗翰八岁，对一种抗生素过敏。药剂师检查了有效期，把剂量写在盒子上，还提醒她这种糖浆可能会让罗翰犯困。到了早上，罗翰的烧退了，还嚷着要吃多萨饼。",
        "services|1:1|4|q0": "米拉为什么晚上去药店？",
