        "services|5:1|0|w0": "申请表",
        "services|5:1|0|w1": "文件",
        "services|5:1|0|w2": "证明",
        "services|5:1|0|w3": "复印件",
        "services|5:1|0|w4": "签名",
        "services|5:1|0|w5": "地址证明",
        "services|5:1|1|p0": "收入证明的申请表在哪里领？",
        "services|5:1|1|p1": "请带上文件原件，每份再附一张复印件。",
        "services|5:1|1|p2": "您忘了在第二页上签名。",
        "services|5:1|1|p3": "电费单可以当地址证明吗？",
        "services|5:1|1|p4": "我的出生证明上，我父亲的名字拼错了。",
        "services|5:1|2|w0": "队伍",
        "services|5:1|2|w1": "号码牌",
        "services|5:1|2|w2": "工作人员",
