        "workplace|5:1|3|p3": "我们的评审能改期到下周吗？我星期一休假。",
        "workplace|5:1|3|p4": "我们的经理很灵活，只要我们至少提前一周申请就行。",
        "workplace|5:1|4|title": "乌杜皮的婚礼",
        "workplace|5:1|4|text": "苏米娅在班加罗尔一家银行总部的支付团队工作。她表姐在乌杜皮的婚礼正好在三月的最后一周，那是一年中最忙的时候。她查了一下剩余假期，发现自己还有九天。她提前三个星期向经理巴特先生请四天假，并礼貌地说明了原因。她还主动提出，婚礼第二天可以在家办公。巴特先生很灵活，但他问谁来顶替她做月底报表。苏米娅和同事拉凯什调换了两个班次，并承诺走之前把工作交接清楚。巴特先生对她的安排很满意，当天下午就批准了她的假。",
        "workplace|5:1|4|q0": "苏米娅为什么要请假？",
        "workplace|5:1|4|q0o0": "参加表姐在乌杜皮的婚礼",
        "workplace|5:1|4|q0o1": "因为她病了",
        "workplace|5:1|4|q0o2": "参加培训课程",
        "workplace|5:1|4|q0o3": "搬新家",
        "workplace|5:1|4|q1": "她还剩几天假？",
        "workplace|5:1|4|q1o0": "九天",
        "workplace|5:1|4|q1o1": "四天",
        "workplace|5:1|4|q1o2": "三天",
        "workplace|5:1|4|q1o3": "十二天",
        "workplace|5:1|4|q2": "谁和苏米娅调换了班次？",
        "workplace|5:1|4|q2o0": "拉凯什",
        "workplace|5:1|4|q2o1": "巴特先生",
        "workplace|5:1|4|q2o2": "她的表姐",
        "workplace|5:1|4|q2o3": "没有人",
        "workplace|5:1|5|title": "一大早的电话",
        "workplace|5:1|5|scenario": "阿伦的妈妈身体不舒服，所以他一大早给组长莎莉妮打了电话。",
        "workplace|5:1|5|l0": "早上好，莎莉妮。抱歉这么早打电话。你现在方便说几句吗？",
        "workplace|5:1|5|l1": "当然，阿伦。一切都好吗？",
        "workplace|5:1|5|l2": "不太好。我妈妈昨晚摔了一跤，我得带她去医院做些检查。",
        "workplace|5:1|5|l3": "哎呀，真让人难过。好好照顾她。你需要请一整天假吗？",
        "workplace|5:1|5|l4": "我想是的。我今天想请一天假，明天也许在家办公。",
        "workplace|5:1|5|l5": "没问题。那三点和客户的电话会议怎么办？",
        "workplace|5:1|5|l6": "迪帕克对这个项目很熟悉。我已经问过他了，他很乐意顶替我。",
        "workplace|5:1|5|l7": "好。请把你的笔记发给他，有空的时候在系统上提交请假申请。",
        "workplace|5:1|5|l8": "我一个小时内就办好。谢谢你的理解，莎莉妮。",
        "workplace|5:1|5|l9": "不客气。希望你妈妈早日康复。",
        "workplace|5:1|5|q0": "阿伦为什么需要请假？",
        "workplace|5:1|5|q0o0": "他妈妈摔了一跤",
        "workplace|5:1|5|q0o1": "他发烧了",
        "workplace|5:1|5|q0o2": "他要参加婚礼",
        "workplace|5:1|5|q0o3": "他的火车被取消了",
        "workplace|5:1|5|q1": "谁会顶替他参加客户电话会议？",
        "workplace|5:1|5|q1o0": "迪帕克",
        "workplace|5:1|5|q1o1": "莎莉妮",
        "workplace|5:1|5|q1o2": "阿伦",
        "workplace|5:1|5|q1o3": "没有人，会议取消了",
        "workplace|5:1|5|q2": "莎莉妮让阿伦做什么？",
        "workplace|5:1|5|q2o0": "把笔记发给迪帕克，并在系统上申请请假",
        "workplace|5:1|5|q2o1": "午饭后来办公室",
        "workplace|5:1|5|q2o2": "取消客户电话会议",
        "workplace|5:1|5|q2o3": "晚上再给她打电话",
        "workplace|6:1|0|w0": "表现",
        "workplace|6:1|0|w1": "优点",
        "workplace|6:1|0|w2": "缺点",
        "workplace|6:1|0|w3": "建设性的",
        "workplace|6:1|0|w4": "自我评估",
        "workplace|6:1|0|w5": "里程碑",
        "workplace|6:1|1|p0": "总的来说，你今年的表现非常出色。",
        "workplace|6:1|1|p1": "你最大的优点，是能冷静地应对生气的顾客。",
        "workplace|6:1|1|p2": "关于昨天的演示，我可以给你一些建设性的意见吗？",
        "workplace|6:1|1|p3": "在自我评估里，我把时间管理列为自己的一个缺点。",
        "workplace|6:1|1|p4": "按时开设迈索尔分公司，是我们团队的一个真正的里程碑。",
        "workplace|6:1|2|w0": "导师",
        "workplace|6:1|2|w1": "提升技能",
        "workplace|6:1|2|w2": "认证证书",
        "workplace|6:1|2|w3": "潜力",
        "workplace|6:1|2|w4": "加薪",
        "workplace|6:1|2|w5": "应得",
        "workplace|6:1|3|p0": "我想提升数据分析方面的技能，公司能资助一门短期课程吗？",
        "workplace|6:1|3|p1": "我的导师建议我在申请组长职位之前，先考一个云计算认证。",
        "workplace|6:1|3|p2": "你的经理认为你有潜力在两年内带领一个团队。",
        "workplace|6:1|3|p3": "今年团队里每个人都会加薪，至少百分之八。",
        "workplace|6:1|3|p4": "我相信我应该得到晋升，也想谈谈下一步是什么。",
        "workplace|6:1|4|title": "考核日",
        "workplace|6:1|4|text": "每年四月，法丽达在门格洛尔的公司都会举行年度考核面谈。在她面谈之前，她写了一份诚实的自我评估，列出了自己的优点，还有一个明显的缺点：她很少向别人求助。她的经理拉奥先生首先表扬了她在新收费系统上的表现，那是团队的一个重要里程碑。接着，他就“更早说出问题”给了她一些建设性的意见。法丽达向他道谢，并申请参加项目管理方面的培训。拉奥先生同意出钱让她参加一门认证课程，还会给她找一位资深导师。他说她有潜力将来带领一个团队，也应该得到一次不错的加薪。法丽达离开会议室时，对新的一年已经有了清晰的计划。",
        "workplace|6:1|4|q0": "法丽达写下了什么缺点？",
        "workplace|6:1|4|q0o0": "她很少向别人求助",
        "workplace|6:1|4|q0o1": "她经常迟到",
        "workplace|6:1|4|q0o2": "她说话太快",
        "workplace|6:1|4|q0o3": "她在收费上出错",
        "workplace|6:1|4|q1": "法丽达申请了什么？",
        "workplace|6:1|4|q1o0": "项目管理方面的培训",
        "workplace|6:1|4|q1o1": "调到浦那工作",
        "workplace|6:1|4|q1o2": "一台新笔记本电脑",
        "workplace|6:1|4|q1o3": "更多假期",
        "workplace|6:1|4|q2": "拉奥先生同意做什么？",
        "workplace|6:1|4|q2o0": "出钱让她上课，并给她找一位导师",
        "workplace|6:1|4|q2o1": "马上让她当经理",
        "workplace|6:1|4|q2o2": "把她调到别的团队",
        "workplace|6:1|4|q2o3": "取消她的考核",
        "workplace|6:1|5|title": "年度评估",
        "workplace|6:1|5|scenario": "拉梅什在班加罗尔的办公室里，和经理苏妮塔进行年度考核面谈。",
        "workplace|6:1|5|l0": "谢谢你过来，拉梅什。我们先从你的自我评估开始吧。你觉得这一年过得怎么样？",
        "workplace|6:1|5|l1": "我觉得挺好的。我们按时交付了支付应用，我还培训了两名新同事。",
        "workplace|6:1|5|l2": "我同意。你在这个应用上的表现非常出色，客户还特别提到了你的工作。",
        "workplace|6:1|5|l3": "听到这个太高兴了。有什么地方您希望我改进吗？",
        "workplace|6:1|5|l4": "只有一点。开会时你经常不说话，即使你有好的想法。我希望你多发言。",
        "workplace|6:1|5|l5": "您说得对。我会尽量早点说出我的想法。我还能申请一些培训吗？",
        "workplace|6:1|5|l6": "当然可以。你想参加什么培训？",
        "workplace|6:1|5|l7": "一门公开演讲课程，也许再从资深团队里找一位导师。",
        "workplace|6:1|5|l8": "这两个想法都很好。我这周就去和人事部谈。继续保持，明年我们可以谈谈让你当组长的事。",
        "workplace|6:1|5|l9": "谢谢您，苏妮塔。真的很感谢您的支持。",
        "workplace|6:1|5|q0": "客户特别提到了什么？",
        "workplace|6:1|5|q0o0": "拉梅什在应用上的工作",
